#!/usr/bin/env bash
# Dev only: generate a random Postgres password and a self-signed TLS certificate.
# Production secrets are generated by deploy/install.sh (Phase 4). Never commit deploy/secrets/.
set -euo pipefail
export MSYS_NO_PATHCONV=1  # Git Bash on Windows would rewrite "/CN=..." into a file path
cd "$(dirname "$0")/.."
umask 077
mkdir -p secrets/tls
if [[ ! -s secrets/pg_password ]]; then
  head -c 32 /dev/urandom | base64 | tr -d '/+=\n' > secrets/pg_password
  echo "created secrets/pg_password"
fi
if [[ ! -s secrets/tls/server.crt ]]; then
  openssl req -x509 -newkey rsa:3072 -sha256 -days 825 -nodes \
    -keyout secrets/tls/server.key -out secrets/tls/server.crt \
    -subj "/CN=airgap.local" \
    -addext "subjectAltName=DNS:airgap.local,DNS:localhost,IP:127.0.0.1"
  echo "created self-signed certificate secrets/tls/server.crt"
fi
